head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "uldmgt50100";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_keyword", fn: function () { return String((dma_pageContext.get("keyword") ?? "")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.search();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50100.onpageload' }); }
};

// [A] 초기 목록 미해결 — 진입 근거가 다른 액션을 가리킨다(element vs byformelement vs extractelement) — 어느 쪽인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_listForm = { action: "", method: 'post', target: '' };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'uldmgt50100.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name form_2_onsubmit
 * @description form_2 onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.form_2_onsubmit = function(e){
    try {
        return false

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50100.form_2_onsubmit' }); }
};

/**
 * @method
 * @name ipt_keyword_onkeyup
 * @description ipt_keyword 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_keyword_onkeyup = async function(e){
    try {
        await scwin.onEnter()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50100.ipt_keyword_onkeyup' }); }
};

/**
 * @method
 * @name img_112_onclick
 * @description img_112 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_112_onclick = async function(e){
    try {
        await scwin.search()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50100.img_112_onclick' }); }
};

/**
 * @method
 * @name img_124_onclick
 * @description 「[없음]」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_124_onclick = async function(e){
    try {
        await scwin.excel()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50100.img_124_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_ShowExtractionStatus
 * @description Show Extraction Status 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_ShowExtractionStatus = async function () {
    const sbmOptions = {
        id: "tx_fn_ShowExtractionStatus",
        method: "post",
        action: "/filing/byformElement.do",
        ref: "dma_ShowExtractionStatusReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_ExtractItem
 * @description Extract Item 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_ExtractItem = async function () {
    const sbmOptions = {
        id: "tx_fn_ExtractItem",
        method: "post",
        action: "/filing/extractElement.do",
        ref: "dma_ExtractItemReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_Excel
 * @description Excel 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Excel = async function () {
    const sbmOptions = {
        id: "tx_fn_Excel",
        method: "post",
        action: "/filing/element.do",
        ref: "dma_ExcelReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_List_xhr
 * @description List xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_List_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_List_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_List_xhr", unresolved: "action:self_submit:tx_fn_List_xhr" };
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name list
 * @description list 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.list = async function () {
    scwin.form_listForm.action = "/filing/element.do";
    $c.util.getComponent('dma_ShowExtractionStatusReq').set('method', "findFormList");
    await scwin.tx_fn_List_xhr();
};

/**
 * @method
 * @name onCompleteResponse
 * @description on Complete Response 처리
 * @param {*} responseText responseText
 * @returns {void}
 * @hidden N
 */
scwin.onCompleteResponse = function (responseText) {
    ($c.util.getComponent('formListDiv') && $c.util.getComponent('formListDiv').setValue) ? $c.util.getComponent('formListDiv').setValue(responseText) : (($c.util.getComponent('formListDiv') && $c.util.getComponent('formListDiv').setText) ? $c.util.getComponent('formListDiv').setText(responseText) : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + 'formListDiv'), void (responseText)));
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    $c.util.getComponent('dma_ShowExtractionStatusReq').set('pageIndex', 1);
    await scwin.list();
};

/**
 * @method
 * @name onEnter
 * @description on Enter 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onEnter = async function () {
    if (event.keyCode === 13) {
        await scwin.search();
    }
};

/**
 * @method
 * @name showExtractionStatus
 * @description show Extraction Status 처리
 * @param {String} formCd formCd
 * @param {*} formVer formVer
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.showExtractionStatus = async function (formCd, formVer) {
    $c.util.getComponent('dma_ShowExtractionStatusReq').set('formCd', formCd);
    $c.util.getComponent('dma_ShowExtractionStatusReq').set('formVer', formVer);
    $c.util.getComponent('dma_ShowExtractionStatusReq').set('method', "findByformElementStatus");
    scwin.form_listForm.target = "";
    scwin.form_listForm.action = "/filing/byformElement.do";
    await scwin.tx_fn_ShowExtractionStatus();
};

/**
 * @method
 * @name extractItem
 * @description extract Item 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.extractItem = async function () {
    let selected = false;
    if (document.listForm.extractTargets.length == null || document.listForm.extractTargets.length === 1) {
        selected = document.listForm.extractTargets.checked;
    } else {
        if (document.listForm.extractTargets.length > 1) {
            for (let i = 0; i < document.listForm.extractTargets.length; i++) {
                if (document.listForm.extractTargets[i].checked) {
                    selected = true;
                    break;
                }
            }
        }
    }
    if (!selected) {
        await $c.win.alert("선택된 서식이 없습니다.");
        return;
    }
    const _url = "about:blank";
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    await $c.win.openPopup((function (__u) { const __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), { id: "extractPop", popupName: "extractPop", width: "300", height: "400" }, {});
    $c.util.getComponent('dma_ShowExtractionStatusReq').set('method', "prepareExtractElement");
    scwin.form_listForm.action = "/filing/extractElement.do";
    scwin.form_listForm.target = "extractPop";
    await scwin.tx_fn_ExtractItem();
};

/**
 * @method
 * @name viewAllFormList
 * @description view All Form List 처리
 * @returns {void}
 * @hidden N
 */
scwin.viewAllFormList = function () {
    const allEditChecked = (document.listForm || { elements: [] }).allEdit.checked;
    let targetArr = [];
    if (document.listForm.extractTargets.length > 1) {
        targetArr = document.listForm.extractTargets;
    } else {
        targetArr[0] = document.listForm.extractTargets;
    }
    for (let i = 0; i < targetArr.length; i++) {
        if (targetArr[i].disabled === false) {
            targetArr[i].checked = allEditChecked;
        }
    }
};

/**
 * @method
 * @name excel
 * @description excel 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excel = async function () {
    scwin.form_listForm.action = "/filing/element.do";
    $c.util.getComponent('dma_ShowExtractionStatusReq').set('method', "downloadFormList");
    scwin.form_listForm.target = "hiddenFrame";
    await scwin.tx_fn_Excel();
};
